fn chebweight(x: Vec<f32>) -> Vec<f32> {
    let n = x.len();
    // Pre-allocate the result vector with the same length as `x`
    let mut result = Vec::with_capacity(n);

    for i in 0..n {
        // Endpoints get weight 0.5, all others get weight 1.0
        let w = if i == 0 || i == n - 1 {
            0.5_f32
        } else {
            1.0_f32
        };
        result.push(w);
    }

    result
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_singleton() {
        // For a single-element array, that element is both start and end -> weight = 0.5
        let x = vec![3.14_f32];
        assert_eq!(chebweight(x), vec![0.5]);
    }

    #[test]
    fn test_two_elements() {
        // Both are endpoints -> both weights = 0.5
        let x = vec![1.0_f32, 2.0];
        assert_eq!(chebweight(x), vec![0.5, 0.5]);
    }

    #[test]
    fn test_multiple_elements() {
        let x = vec![0.0_f32, 1.0, 2.0, 3.0, 4.0];
        // endpoints = 0.5, interiors = 1.0
        assert_eq!(chebweight(x), vec![0.5, 1.0, 1.0, 1.0, 0.5]);
    }
}